            return self.vm.rareData().filePolls(self.vm).get();
    }

pub inline fn platformEventLoop(self: JsVM) *jsc.PlatformEventLoop {
            return self.vm.event_loop_handle.?;
    }

pub inline fn incrementPendingUnrefCounter(self: JsVM) void {
            self.vm.pending_unref_counter = (self.vm.pending_unref_counter +| 1);
    }

