const ConcurrentTaskQueueT = UnboundedQueue(AnyTaskWithExtraContext, .next);
pub threadlocal var globalInitialized: bool = false;
pub threadlocal var global: *MiniEventLoop = undefined;

pub fn AbstractVM(inner: anytype) switch (@TypeOf(inner)) {
    *VirtualMachine => JsVM,
    *jsc.MiniEventLoop => MiniVM,
    else => @compileError("Invalid event loop ctx"),
} {
        if (comptime (@TypeOf(inner) == *VirtualMachine)) {
            return JsVM.init(inner);
        }
        if (comptime (@TypeOf(inner) == *jsc.MiniEventLoop)) {
            return MiniVM.init(inner);
        }
        _ = @compileError("Invalid event loop ctx");
}
